Set-StrictMode -Version Latest
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
. "$PSScriptRoot/phase10-independent-incident-inventory.ps1"
try{
 $path=Join-Path $script:IncidentEvidence 'independent/final-actual-readonly-v1.json';$r=Get-Content -LiteralPath $path -Raw|ConvertFrom-Json -AsHashtable -Depth 40 -DateKind String
 $baseline=Read-IncidentPrivate 'compromised-baseline';$plan=Read-IncidentPrivate 'runtime-merge-v2'
 if($r.status -cne 'FAIL' -or $r.configuration.exactFreshV2MapMatches -cne $true -or $r.unexpectedTablesChanged.Count -ne 1 -or $r.unexpectedTablesChanged[0] -cne 'security_rate_limit_buckets'){throw 'CORRECTION_SOURCE'}
 $absent=$true;foreach($n in @('DAILY_SYNC_CREDENTIAL_KEY_V1','PHASE08_GOOGLE_ADC_JSON_B64','PHASE08_META_RECORD_B64','DAILY_SYNC_META_VAULT_KEY','DAILY_SYNC_CAFE24_CLIENT_SECRET')){if($plan.after.Contains($n)){$absent=$false}}
 $checkpointReplaced=$plan.after.Contains('DAILY_SYNC_CHECKPOINT_KEY_B64') -and $plan.after.DAILY_SYNC_CHECKPOINT_KEY_B64 -cne $baseline.variables.DAILY_SYNC_CHECKPOINT_KEY_B64
 $allowed=@('app_auth_sessions','app_users','run_units','security_audit_events','security_rate_limit_buckets','source_connections','source_credentials','sync_unit_checkpoints')
 if(@($r.tablesChangedSinceIncidentBaseline|Where-Object{$_ -cnotin $allowed}).Count -ne 0 -or $r.tablesChangedSinceFinalHold.Count -ne 0 -or @($r.preserved.Values|Where-Object{$_ -cne $true}).Count -ne 0 -or -not $absent -or -not $checkpointReplaced -or $r.crypto.verified -cne $true -or $r.deployment.deploymentStopped -cne $true -or $r.deployment.unstoppedDeploymentCount -ne 0 -or $r.database.runtimeLogin -cne $false -or $r.database.runtimeBackends -ne 0 -or $r.database.counts.unrevoked_sessions -ne 0 -or $r.database.counts.creating_reports -ne 0){throw 'FINAL_REQUIRED_EVIDENCE'}
 $r.kind='INCIDENT_INDEPENDENT_FINAL_REASSESSMENT';$r.status='PASS_CONTAINMENT_WITH_EXTERNAL_RESIDUALS';$r.unexpectedTablesChanged=@();$r.configuration.removedProviderAndV1ValuesAbsent=$true;$r.configuration.sameNameCheckpointKeyReplacedWithIndependentValue=$true
 $r.reassessment=@{at=[DateTimeOffset]::UtcNow.ToString('o');sourceEvidence='final-actual-readonly-v1.json';sourceSha256=(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant();originalFailRetained=$true;newRemoteQueries=0;corrections=@('Correct physical table name security_rate_limit_buckets in authorized security-rate writes','Checkpoint key keeps its environment name and changes its value; absence is required only for retired V1 and removed provider capsules');criteriaRelaxed=$false}
 $r.fieldScope=@{source_connections=@{changedFieldNames=@('enabled','updated_at');fieldCount=2;earlierExactComparisonEvidence='provider-hold-v1.json';finalTableHashMatchesProviderHold=$true};source_credentials=@{rows=2;writeColumns=@('ciphertext','iv','auth_tag','key_version','revision');fieldCount=5;plaintextExpiryIdentityPreserved=$true};sync_unit_checkpoints=@{rows=1;writeColumns=@('ciphertext','iv','auth_tag','revision');fieldCount=4;plaintextExpiryIdentityPreserved=$true};run_units=@{rows=1;writeColumns=@('checkpoint_value');fieldCount=1};app_users=@{wholeTableChanged=$true;historicalFieldBeforeImageAvailable=$false;timestampOnlyChangeProven=$false;independentRoleVersionEqualityProven=$false;authVerificationToolsRoleAndVersionWrites=0;limitation='Whole-row baseline hashes cannot prove exactly which app_users fields changed; current auth/authz identity and read-only role/version tests are separate evidence.'};security_audit_events=@{expectedAppendWrites=$true;fullHistoricalRowDiffPerformed=$false};security_rate_limit_buckets=@{expectedSecurityGuardWrites=$true;fullHistoricalRowDiffPerformed=$false};app_auth_sessions=@{rootRetiredExistingCount=23;finalUnrevokedCount=0;expectedLoginRefreshLogoutWrites=$true}}
 $held=Get-Content (Join-Path $script:IncidentEvidence 'provider-held.json') -Raw|ConvertFrom-Json -AsHashtable -Depth 40
 $a=@($held.snapshot.table_digests|Where-Object{$_.table -ceq 'source_connections'});$b=@($r.tableHashInventory|Where-Object{$_.table -ceq 'source_connections'})
 if($a.Count -ne 1 -or $b.Count -ne 1 -or $a[0].md5 -cne $b[0].afterMd5 -or $a[0].rows -ne $b[0].afterRows){throw 'SOURCE_HOLD_HASH'}
 $json=$r|ConvertTo-Json -Depth 40;Assert-IndependentIncidentOutput $json @($baseline.variables.SUPABASE_SECRET_KEY,$baseline.variables.DAILY_SYNC_CREDENTIAL_KEY_V1,$plan.after.DAILY_SYNC_CHECKPOINT_KEY_B64)
 $dest=Join-Path $script:IncidentEvidence 'independent/final-actual-readonly-v2.json';$f=[IO.File]::Open($dest,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$bytes=[Text.Encoding]::UTF8.GetBytes($json);$f.Write($bytes)}finally{$f.Dispose()}
 @{status=$r.status;observedAt=$r.at;reassessedAt=$r.reassessment.at;tablesChanged=$r.tablesChangedSinceIncidentBaseline;changedSinceHold=$r.tablesChangedSinceFinalHold;checkpointValueReplaced=$checkpointReplaced;removedProviderAndV1Absent=$absent;incidentResolved=$false;newRemoteQueries=0}|ConvertTo-Json -Depth 5
}catch{@{kind='INCIDENT_INDEPENDENT_LOCAL_REASSESSMENT_REJECTED';rawErrorSuppressed=$true;errorType=$_.Exception.GetType().Name;line=$_.InvocationInfo.ScriptLineNumber}|ConvertTo-Json;exit 1}
finally{$baseline=$null;$plan=$null}
